spec.expr:
label_join(
  label_replace(
    sum by (server, profile) (
      increase(
        pytorrent_transfer_downloaded_bytes{
          server=~"$server",
          profile=~"$profile"
        }[$__range]
      )
    ),
    "transfer_type", "Download", "profile", ".*"
  ),
  "target", " / ", "server", "profile"
)

label_join(
  label_replace(
    sum by (server, profile) (
      increase(
        pytorrent_transfer_uploaded_bytes{
          server=~"$server",
          profile=~"$profile"
        }[$__range]
      )
    ),
    "transfer_type", "Upload", "profile", ".*"
  ),
  "target", " / ", "server", "profile"
)

label_join(
  sum by (server, profile, state) (
    pytorrent_torrents{
      server=~"$server",
      profile=~"$profile",
      state=~"downloading|queued|seeding|paused|checking|error|post_check|stopped"
    }
  ),
  "target", " / ", "server", "profile"
)
